import { useMemo, useRef, useState } from "react";

type InputProps = {
  options: string[];
  value?: string; // Controlled when provided
  defaultValue?: string;
  onChange?: (value: string) => void;
  validate?: (value: string) => boolean;
  maxResults?: number;
};

export function Input({
  options,
  value,
  defaultValue = "",
  onChange,
  validate,
  maxResults = 50,
}: InputProps) {
  const [draft, setDraft] = useState(defaultValue);
  const [open, setOpen] = useState(false);
  const [activeIndex, setActiveIndex] = useState(-1);
  const rootRef = useRef<HTMLDivElement>(null);

  const currentValue = value ?? draft;
  const isValid = validate ? validate(currentValue) : true;

  const matches = useMemo(() => {
    const query = currentValue.trim().toLocaleLowerCase();
    if (!query || maxResults <= 0) return [];

    const result: string[] = [];
    for (const option of options) {
      if (option.toLocaleLowerCase().includes(query)) {
        result.push(option);
        if (result.length === maxResults) break;
      }
    }
    return result;
  }, [currentValue, maxResults, options]);

  const updateValue = (next: string) => {
    if (value === undefined) setDraft(next);
    onChange?.(next);
    setActiveIndex(-1);
    setOpen(true);
  };

  const select = (option: string) => {
    updateValue(option);
    setOpen(false);
  };

  return (
